        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
            raise ValueError("Capacity must be a positive integer")
        self.capacity = capacity
        self.clock = clock
        self.items = OrderedDict()

    def put(self, key, value, ttl):
        if ttl <= 0:
            return  # Remove the key if it exists, don't insert new one
        self.items[key] = (value, self.clock() + ttl)
        # Move to end (most recent) - actually for LRU we want to move to end
        # but OrderedDict.popitem(last=False) removes from beginning (least recent)
        # So we need to move the key to end first, then pop from beginning
        if key in self.items:
            del self.items[key]
        self.items[key] = (value, self.clock() + ttl)
        # Remove expired entries before eviction
        expired_keys = [k for k, (v, e) in self.items.items() if self.clock() >= e]
        for k in expired_keys:
            del self.items[k]
        if len(self.items) > self.capacity:
            self.items.popitem(last=False)  # Remove least recently used (first item)

    def get(self, key, default=None):
        if key not in self.items:
            return default
        value, expires = self.items[key]
        if self.clock() >= expires:
            del self.items[key]  # Remove expired entry
            return default
        # Update recency - move to end
        del self.items[key]
        self.items[key] = (value, self.clock() + float('inf'))  # Mark as never expiring after access
        return value
